import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { readFileSync, writeFileSync } from "fs";

// Read and normalize the trial id
const rawTrialId = readFileSync("/logs/artifacts/trial_id", "utf-8").trim();
const trialId = rawTrialId.toLowerCase().replace(/[^a-z0-9.\-]/g, "-");

// Build the four normalized workspace names
const names = [1, 2, 3, 4].map(
  (i) => `pool-agent-${trialId}-${i}`
);

console.log("Trial ID (raw):", rawTrialId);
console.log("Trial ID (normalized):", trialId);
console.log("Workspace names:", names);

// ── 1. Provision all four workspaces concurrently ──────────────────────────
console.log("\nProvisioning workspaces in parallel…");
const creationResults = await Promise.all(
  names.map((name) =>
    createWorkspace(name, {
      ttl: { days: 1 },
      credentials: { role: "Editor" },
    })
  )
);

// Surface any creation errors and exit non-zero
const creationErrors: string[] = [];
const workspaces = creationResults.map((result, i) => {
  if (result.error) {
    creationErrors.push(`[${names[i]}] ${result.error.message ?? result.error}`);
    return null;
  }
  console.log(`  ✓ Created workspace "${names[i]}" → bucket: ${result.data!.bucket}`);
  return result.data!;
});

if (creationErrors.length > 0) {
  console.error("\nWorkspace creation failed:");
  creationErrors.forEach((e) => console.error(" ", e));
  process.exit(1);
}

// TypeScript guard – all entries are non-null at this point
const validWorkspaces = workspaces as NonNullable<(typeof workspaces)[number]>[];

// ── 2. Upload init.txt into every workspace in parallel ────────────────────
console.log("\nUploading init.txt objects in parallel…");
await Promise.all(
  validWorkspaces.map((ws, i) => {
    const agentName = names[i];
    const client = new S3Client({
      endpoint: "REDACTED",
      region: "REDACTED",
      credentials: {
        accessKeyId: ws.credentials!.accessKeyId,
        secretAccessKey: ws.credentials!.secretAccessKey,
      },
      forcePathStyle: false,
    });
    return client
      .send(
        new PutObjectCommand({
          Bucket: ws.bucket,
          Key: "init.txt",
          Body: agentName,
          ContentType: "text/plain",
        })
      )
      .then(() => {
        console.log(`  ✓ Uploaded init.txt to "${agentName}" (bucket: ${ws.bucket})`);
      });
  })
);

// ── 3. Write pool.json summary ─────────────────────────────────────────────
const summary = validWorkspaces.map((ws, i) => ({
  name: names[i],
  bucket: ws.bucket,
}));

writeFileSync(
  "/home/user/ws-pool/pool.json",
  JSON.stringify(summary, null, 2)
);
console.log("\npool.json written:");
console.log(JSON.stringify(summary, null, 2));

// ── 4. Tear down every workspace resiliently ───────────────────────────────
console.log("\nTearing down workspaces…");
const teardownResults = await Promise.allSettled(
  validWorkspaces.map((ws) => teardownWorkspace(ws))
);

teardownResults.forEach((result, i) => {
  if (result.status === "fulfilled") {
    if (result.value.error) {
      console.warn(
        `  ⚠ Teardown of "${names[i]}" returned error:`,
        result.value.error
      );
    } else {
      console.log(`  ✓ Torn down "${names[i]}"`);
    }
  } else {
    console.warn(`  ⚠ Teardown of "${names[i]}" rejected:`, result.reason);
  }
});

console.log("\nDone.");
process.exit(0);
